JedisPoolConfig poolConfig = new JedisPoolConfig();
poolConfig.setMaxTotal(100);
JedisPool jedisPool = new JedisPool(poolConfig, "localhost", 6379);

try (Jedis jedis = jedisPool.getResource()) {
    jedis.set("user:01:name", "Alice");
    String name = jedis.get("user:01:name");
    jedis.setex("session:token", 3600, "abc123");
    jedis.incr("article:views:1001");
}

try (Jedis jedis = jedisPool.getResource()) {
    jedis.hset("product:1001", "name", "iPhone 15");
    jedis.hset("product:1001", "price", "7999");
    String price = jedis.hget("product:1001", "price");
    Map<String, String> product = jedis.hgetAll("product:1001");
}
